import {THEMES,PROFILES} from './model.js';
import {ensureLevels,courseFor,courseKey} from './levels.js';
export const stageKey=(pack,world,stage)=>courseKey(pack,world)+'~'+stage;
export function ensureJourneys(p){ensureLevels(p);p.stageCourses??={};p.originalCourses??={};p.journeys??={runner:{},original:{}};for(const mode of ['runner','original'])p.journeys[mode]??={};for(const r of Object.values(p.courses)){p.stageCourses[stageKey(r.packId,r.theme,r.stage)]??=structuredClone(r);const j=journey(p,'runner',r.theme);for(const n of r.claimedStages||[])if(!j.completed.includes(n))j.completed.push(n);}if(!p.journeyMigrated)for(const h of Object.values(p.levelProgress))for(const [world,w]of Object.entries(h.worlds||{})){const j=journey(p,'runner',world);for(const n of w.stageIds||[])if(!j.completed.includes(n))j.completed.push(n);}p.journeyMigrated=true;if(!p.lastAdventure){const r=p.courses[courseKey(p.activePack,p.theme)]||Object.values(p.courses).find(r=>r.packId===p.activePack);if(r)p.lastAdventure={mode:'runner',world:r.theme,stage:r.stage,packId:r.packId};}return p.journeys;}
export function journey(p,mode,world){p.journeys??={runner:{},original:{}};p.journeys[mode]??={};return p.journeys[mode][world]??={completed:[]};}
export function completedStage(p,mode,world,stage){const j=journey(p,mode,world);if(!j.completed.includes(stage))j.completed.push(stage);j.completed.sort();}
export function stageCourse(p,pack,world,stage){ensureJourneys(p);const r=p.stageCourses[stageKey(pack,world,stage)]||courseFor(p,pack,world);return r?.stage===stage?r:null;}
export function nextGameplayStage(p,mode,world){const j=journey(p,mode,world);return [0,1,2].find(n=>!j.completed.includes(n))??0;}
function unfinished(mode,saved){return !!saved&&(mode==='runner'?!['stage','victory'].includes(saved.mode):!saved.completed);}
export function mapArt(world){const t=THEMES[world],sky='#'+t.sky.toString(16).padStart(6,'0'),edge='#'+t.edge.toString(16).padStart(6,'0');const art={
volcano:'<path d="M0 90L65 12 125 90M80 90L132 35 180 90" fill="#785268"/><path d="M48 35L65 12 85 39 66 32Z" fill="#ffb48a"/><path d="M66 34L79 77" stroke="#ff986d" stroke-width="7"/>',
cosmic:'<g fill="#fff3c0"><circle cx="20" cy="20" r="2"/><circle cx="118" cy="14" r="2"/><circle cx="160" cy="50" r="2"/></g><circle cx="57" cy="34" r="24" fill="#ba9fdb"/><ellipse cx="57" cy="34" rx="36" ry="8" fill="none" stroke="#f6d5a1" stroke-width="5" transform="rotate(-20 57 34)"/><path d="M120 58h48v25h-48z" fill="#b4dce0"/>',
jungle:'<g stroke="#875e57" stroke-width="9"><path d="M22 90V24m58 66V14m72 76V27"/></g><g fill="#499b74"><circle cx="22" cy="25" r="29"/><circle cx="80" cy="15" r="35"/><circle cx="152" cy="26" r="33"/></g><path d="M23 30q20 65 59-8" fill="none" stroke="#a2c578" stroke-width="3"/>',
underwater:'<path d="M12 90V48m0 16L2 56m10 19 17-18M156 90V39m0 19-17-13m17 28 19-19" stroke="#ffafbd" stroke-width="9" fill="none"/><path d="M55 85V44h65v41M48 42h80" fill="#83bfc6" stroke="#caf1dd" stroke-width="6"/><g fill="none" stroke="#d4f5fa"><circle cx="36" cy="19" r="6"/><circle cx="140" cy="28" r="4"/></g>',
castle:'<path d="M35 90V30h28v22h54V30h28v60z" fill="#b9a2cb"/><path d="M29 30l20-23 20 23M111 30l20-23 20 23" fill="#d9b98e"/><path d="M77 90V67q13-20 26 0v23" fill="#514d75"/>',
haunted:'<path d="M12 90l18-70 12 70M130 90l12-80 16 80" fill="#4b5270"/><path d="M60 65q-10-48 15-48t20 48l-9-6-7 7-8-7Z" fill="#bfebdc"/><g fill="#435775"><circle cx="70" cy="35" r="3"/><circle cx="82" cy="35" r="3"/></g><path d="M113 90V71" stroke="#e9cca8" stroke-width="5"/><ellipse cx="113" cy="70" rx="15" ry="7" fill="#cf9cdb"/>',
frozen:'<path d="M0 90L62 8 124 90M85 90l53-65 42 65" fill="#a1cce1"/><path d="M40 38L62 8 85 40 63 30zM123 45l15-20 14 22-14-7z" fill="#f4fcff"/><path d="M0 85q70-20 180 1" fill="none" stroke="#dbf5f2" stroke-width="8"/>'
}[world];return `<svg viewBox="0 0 180 90" aria-hidden="true"><rect width="180" height="90" rx="15" fill="${sky}"/>${art}<path d="M70 90L95 66h10l28 24" fill="${edge}" opacity=".7"/></svg>`;}
export function adventureMap({p,pack,mode,profile,world=p.theme}){ensureJourneys(p);const t=THEMES[world],j=journey(p,mode,world),savedNext=[0,1,2].find(i=>unfinished(mode,mode==='runner'?stageCourse(p,pack.id,world,i):p.originalCourses[stageKey(pack.id,world,i)])),next=savedNext??nextGameplayStage(p,mode,world);return `<section class="adventure-map"><header class="map-top"><button id="map-back">‹ Games</button><div><small>${PROFILES[profile].name} · ${mode==='runner'?'CRYSTAL QUEST':PROFILES[profile].subtitle}</small><h2>Adventure Map</h2></div><span class="map-study">📖 ${escapeText(pack.title)} <button id="map-change-test">Change Test</button></span></header><div class="map-layout"><nav class="destination-grid" aria-label="Fantasy destinations">${Object.entries(THEMES).map(([id,t])=>`<button data-destination="${id}" class="destination ${id===world?'selected':''}" aria-pressed="${id===world}">${mapArt(id)}<strong>${t.name}</strong><small>${journey(p,mode,id).completed.length}/3 stages complete</small></button>`).join('')}</nav><section class="stage-panel"><div class="stage-world-art">${mapArt(world)}</div><h3>${t.name}</h3><p>Three gameplay stages · ${j.completed.length}/3 complete</p><div class="stage-path">${t.stages.map((name,i)=>{const saved=mode==='runner'?stageCourse(p,pack.id,world,i):p.originalCourses[stageKey(pack.id,world,i)];const done=j.completed.includes(i),resume=unfinished(mode,saved);return `<button data-stage="${i}" class="stage-stop ${i===next?'next':''}"><b>${done?'✓':i+1}</b><span><strong>${name}</strong><small>Stage ${i+1} · ${resume?'Saved checkpoint':done?'Complete · replay':'Ready to explore'}</small></span><em>${resume?'Continue':'Play'} ›</em></button>`;}).join('')}</div><button class="primary" id="map-next" data-next="${next}">${savedNext!==undefined?'Continue Saved Stage':j.completed.length===3?'Play Again':'Continue Next Stage'} ➜</button></section></div><footer class="map-footer">Your test supplies questions. Destinations and stages stay available when your test changes.<button id="map-menu">Back to Games</button></footer></section>`;}
function escapeText(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
